<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$st=$pdo->prepare("SELECT COUNT(*) count_sales,COALESCE(SUM(total),0) revenue,COALESCE(SUM(paid_amount),0) collected,COALESCE(SUM(balance),0) due FROM sales WHERE DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$summary=$st->fetch();$st=$pdo->prepare("SELECT si.product_name,SUM(si.qty) qty,SUM(si.line_total) revenue,SUM((si.unit_price-si.cost_price)*si.qty) profit FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE DATE(s.created_at) BETWEEN ? AND ? GROUP BY si.product_id,si.product_name ORDER BY qty DESC LIMIT 10");$st->execute([$from,$to]);$items=$st->fetchAll();layout_start('Reports','reports');?>
<section class="panel form-panel"><form method="get" class="form-grid"><label>From date<input type="date" name="from" value="<?=h($from)?>" required></label><label>To date<input type="date" name="to" value="<?=h($to)?>" required></label><div class="form-actions"><button class="btn primary">Run report</button></div></form></section><div class="stats-grid"><article class="stat-card"><span class="muted">Gross sales</span><strong><?=money($summary['revenue'])?></strong><small><?=$summary['count_sales']?> transactions</small></article><article class="stat-card"><span class="muted">Collected</span><strong><?=money($summary['collected'])?></strong></article><article class="stat-card"><span class="muted">Outstanding balance</span><strong><?=money($summary['due'])?></strong></article><article class="stat-card"><span class="muted">Estimated product profit</span><strong><?=money(array_sum(array_column($items,'profit')))?></strong><small>Based on stored cost prices</small></article></div><section class="panel table-panel"><div class="panel-head"><div><h3>Best-selling items</h3><p class="muted">Selected period: <?=h($from)?> to <?=h($to)?></p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units sold</th><th class="right">Revenue</th><th class="right">Estimated profit</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td><?=$i['qty']?></td><td class="right"><?=money($i['revenue'])?></td><td class="right"><?=money($i['profit'])?></td></tr><?php endforeach;if(!$items):?><tr><td colspan="4" class="empty">No sales in this period.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>
